What will be the output of the following C++ code? 
#include <iostream>
#include <stdarg.h>
using namespace std;
int add (int num, ...)
{
 int sum = 0;
 va_list args;
 va_start (args,num);
 for (int i = 0; i < num; i++) 
 {
 int num = va_arg (args,int);
 sum += num;
 }
 va_end (args);
 return sum;
}
int main (void)
{
 int total = add(8, 1, 2, -1, 4, 12, -2, 9, 7);
 cout << "The result is " << total;
 return 0;
}

What will be the output of the following C++ code? 
#include <iostream>
#include <stdarg.h>
using namespace std;
void dumplist(int, ...);
int main()
{
 dumplist(2, 4, 8);
 dumplist(3, 6, 9, 7);
 return 0;
}
void dumplist(int n, ...)
{
 va_list p;
 int i;
 va_start(p, n);
 while (n-->0) 
 {
 i = va_arg(p, int);
 cout << i;
 }
 va_end(p);
}

